class JoinGuard {
public:
    explicit JoinGuard(std::thread& t) : t_(t) {}
    ~JoinGuard() { if (t_.joinable()) t_.join(); }
    JoinGuard(const JoinGuard&) = delete;
    JoinGuard& operator=(const JoinGuard&) = delete;
