    for (int i = 0; i < 100000; ++i) {
        std::scoped_lock lk(m1, m2);   // locks both, unlocks both
        ++x; ++y;
    }
}

int main() {
    std::thread t1(update), t2(update);
    t1.join();
    t2.join();
    std::cout << x << ' ' << y << '\n';   // 200000 200000
