#include <semaphore>
#include <thread>

std::binary_semaphore go{0};   // no owner: any thread may release

int main() {
    std::thread t([] {
        std::cout << "worker: signalling\n";
        go.release();
    });
    go.acquire();                               // waits for the worker's signal
    std::cout << "main: got the signal\n";
    t.join();
}
```

