    std::mutex m;
    long balance = 0;
};

int main() {
    std::deque<Account> accounts;   // emplace_back never moves existing elements
    accounts.emplace_back();
    accounts.emplace_back();
    std::cout << accounts.size() << '\n';   // 2
}
```

