        std::unique_lock<std::mutex> lk(m);
        while (true) {
            // returns pred(); wakes on notify OR on a stop request
            if (!cv.wait(lk, st, [&] { return !q.empty(); }))
                break;                         // stop requested, queue empty
            q.pop();
