class SpinLock {
    std::atomic<bool> locked_{false};
public:
    void lock() {
        for (;;) {
            if (!locked_.exchange(true, std::memory_order_acquire)) return;  // acquire on success
            while (locked_.load(std::memory_order_relaxed)) {}  // spin on loads (test-and-test-and-set)
