#include <iostream>
#include <thread>

int data = 0;
std::atomic<bool> ready{false};

void producer() {
    data = 42;
    ready.store(true, std::memory_order_release);      // publish
}

void consumer() {
    while (!ready.load(std::memory_order_acquire)) {}  // import
    std::cout << data << '\n';                          // always 42
}

int main() {
    std::thread c(consumer), p(producer);
    p.join();
    c.join();
}
```

