    void unlock() { flag_.clear(std::memory_order_release); }
};

SpinLock a, b;
int x = 0, y = 0;

int main() {
    {
        std::scoped_lock both(a, b);
        ++x;
        ++y;
    }
    std::cout << "x=" << x << " y=" << y << '\n';
}

